def _make_toml(path: Path, data: dict) -> None:
    with open(path, "w") as f:
        f.write("# auto-generated\n")
        for k, v in data.items():
            f.write(f"[{k}]\n")
            if isinstance(v, dict):
                for sk, sv in v.items():
                    f.write(f"  {sk} = {sv}\n")
            else:
                f.write(f"  {k} = {v}\n")
